import{_ as e,o as a,c as o,a2 as n}from"./chunks/framework.CsGzzEsd.js";const c=JSON.parse('{"title":"Japanese Grammar Foundations","description":"","frontmatter":{"title":"Japanese Grammar Foundations"},"headers":[],"relativePath":"blogs/JLPT-N2/grammars.md","filePath":"blogs/JLPT-N2/grammars.md"}'),s={name:"blogs/JLPT-N2/grammars.md"};function r(i,t,l,h,g,d){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="japanese-grammar-foundations" tabindex="-1">Japanese Grammar Foundations <a class="header-anchor" href="#japanese-grammar-foundations" aria-label="Permalink to &quot;Japanese Grammar Foundations&quot;">​</a></h1><p>These basic patterns are useful to review before studying N2 grammar. In the patterns below, <strong>N</strong> means a noun, and <strong>A/B</strong> stand for words or phrases in the sentence.</p><h2 id="a-は-b-です" tabindex="-1">A は B です <a class="header-anchor" href="#a-は-b-です" aria-label="Permalink to &quot;A は B です&quot;">​</a></h2><p><strong>Rule:</strong> は (pronounced <em>wa</em>) marks the topic: “as for A.” です makes a noun or な-adjective predicate polite. The topic is not always the grammatical subject.</p><ul><li>私は留学生です。 — I am an international student.</li><li>あの方は先生です。 — That person is a teacher.</li></ul><p><strong>Negative:</strong> A は B ではありません (or the conversational B じゃありません).</p><ul><li>私は先生ではありません。 — I am not a teacher.</li></ul><p><strong>Question:</strong> Add か to the end of a polite sentence. In writing, a question mark is optional.</p><ul><li>あの方は先生ですか。 — Is that person a teacher?</li></ul><p><strong>Connecting predicates:</strong> B で connects a noun or な-adjective predicate to another predicate. This で is a connective form of the copula, not the particle for the location of an action.</p><ul><li>田中さんは先生で、作家です。 — Tanaka is a teacher and a writer.</li></ul><h2 id="demonstratives" tabindex="-1">Demonstratives <a class="header-anchor" href="#demonstratives" aria-label="Permalink to &quot;Demonstratives&quot;">​</a></h2><p><strong>Rule:</strong> The first syllable shows where the referent is relative to the speakers: <strong>こ</strong> near the speaker, <strong>そ</strong> near the listener or something already mentioned, <strong>あ</strong> away from both, and <strong>ど</strong> for a question. In conversation, そ and あ can also refer to familiar or remembered things; physical distance is only the starting point.</p><table tabindex="0"><thead><tr><th>Position</th><th>Thing</th><th>Place</th><th>Direction / polite person</th></tr></thead><tbody><tr><td>Near speaker</td><td>これ</td><td>ここ</td><td>こちら</td></tr><tr><td>Near listener</td><td>それ</td><td>そこ</td><td>そちら</td></tr><tr><td>Away from both</td><td>あれ</td><td>あそこ</td><td>あちら</td></tr><tr><td>Question</td><td>どれ</td><td>どこ</td><td>どちら</td></tr></tbody></table><ul><li>これは私の本です。 — This is my book.</li><li>駅はどちらですか。 — Which way is the station? (polite)</li></ul><p>こちら／そちら／あちら／どちら can also politely refer to a person or choice, depending on context.</p><h2 id="n1-に-n2-が-あります-います" tabindex="-1">N1 に N2 が あります／います <a class="header-anchor" href="#n1-に-n2-が-あります-います" aria-label="Permalink to &quot;N1 に N2 が あります／います&quot;">​</a></h2><p><strong>Rule:</strong> This pattern introduces N2 as existing at N1. に marks the location; が marks what exists. Use <strong>あります</strong> for things and plants, and <strong>います</strong> for people and animals.</p><ul><li>机の上に本があります。 — There is a book on the desk.</li><li>教室に学生がいます。 — There are students in the classroom.</li></ul><p>For possession, the location can be a person: 私には兄がいます。 — I have an older brother (literally, “As for me, an older brother exists”).</p><h2 id="n1-には-n2-が-あります-います" tabindex="-1">N1 には N2 が あります／います <a class="header-anchor" href="#n1-には-n2-が-あります-います" aria-label="Permalink to &quot;N1 には N2 が あります／います&quot;">​</a></h2><p><strong>Rule:</strong> には combines the location marker に with the topic or contrast marker は. It makes N1 the frame of the statement and can imply a contrast with other places or people. Use があります／います according to N2.</p><ul><li>この町には大きな公園があります。 — This town has a large park.</li><li>私のクラスには留学生がいます。 — There are international students in my class.</li></ul><p>Compare <strong>教室に学生がいます</strong> (“There are students in the classroom”) with <strong>教室には学生がいます</strong> (“In the classroom, there are students”), which puts more focus on the classroom.</p><h2 id="n1-は-n2-に-あります-います" tabindex="-1">N1 は N2 に あります／います <a class="header-anchor" href="#n1-は-n2-に-あります-います" aria-label="Permalink to &quot;N1 は N2 に あります／います&quot;">​</a></h2><p><strong>Rule:</strong> Use this order when N1 is already known and you want to say <strong>where</strong> it is. は marks the known topic; に marks its location. Choose あります／います according to N1.</p><ul><li>本は机の上にあります。 — The book is on the desk.</li><li>先生は職員室にいます。 — The teacher is in the staff room.</li></ul><p>Compare <strong>机の上に本があります</strong> (“There is a book on the desk”), which introduces the book, with <strong>本は机の上にあります</strong> (“The book is on the desk”), which gives the location of a known book.</p><h2 id="past-tense-noun-predicates" tabindex="-1">Past tense: noun predicates <a class="header-anchor" href="#past-tense-noun-predicates" aria-label="Permalink to &quot;Past tense: noun predicates&quot;">​</a></h2><p><strong>Rule:</strong> For a polite noun sentence, change です to <strong>でした</strong>. The polite negative past is <strong>ではありませんでした</strong> (or conversational <strong>じゃありませんでした</strong>). These forms also work with な-adjective predicates.</p><table tabindex="0"><thead><tr><th>Meaning</th><th>Pattern</th><th>Example</th></tr></thead><tbody><tr><td>Past affirmative</td><td>A は B でした</td><td>昨日は休みでした。 — Yesterday was a day off.</td></tr><tr><td>Past negative</td><td>A は B ではありませんでした</td><td>昨日は休みではありませんでした。 — Yesterday was not a day off.</td></tr></tbody></table><p>The plain forms are <strong>だった</strong> and <strong>ではなかった</strong> (or <strong>じゃなかった</strong>): 昨日は休みだった。 — Yesterday was a day off.</p><h2 id="past-tense-verb-predicates" tabindex="-1">Past tense: verb predicates <a class="header-anchor" href="#past-tense-verb-predicates" aria-label="Permalink to &quot;Past tense: verb predicates&quot;">​</a></h2><p><strong>Rule:</strong> A polite verb changes from <strong>～ます</strong> to <strong>～ました</strong> in the affirmative past, and from <strong>～ません</strong> to <strong>～ませんでした</strong> in the negative past. The plain past form depends on the verb group, so it cannot be made by simply replacing ます with た.</p><table tabindex="0"><thead><tr><th>Meaning</th><th>Polite</th><th>Plain</th></tr></thead><tbody><tr><td>Past affirmative</td><td>昨日、映画を見ました。 — I watched a film yesterday.</td><td>昨日、映画を見た。</td></tr><tr><td>Past negative</td><td>昨日、映画を見ませんでした。 — I did not watch a film yesterday.</td><td>昨日、映画を見なかった。</td></tr></tbody></table><p>For example, 行きます → 行きました → 行った, while 食べます → 食べました → 食べた.</p><h2 id="question-words-with-が" tabindex="-1">Question words with が <a class="header-anchor" href="#question-words-with-が" aria-label="Permalink to &quot;Question words with が&quot;">​</a></h2><p><strong>Rule:</strong> When a question word asks <strong>who or what the subject is</strong>, mark it with が: 誰が／何が. The answer commonly uses が to identify that subject. Use は instead if the answer treats the person or thing as an established topic or makes a contrast; “a が question must be answered with が” is too absolute.</p><ul><li>誰が来ましたか。 — Who came?</li><li>田中さんが来ました。 — Tanaka came.</li><li>何がありますか。 — What is there?</li><li>机の上に本があります。 — There is a book on the desk.</li></ul><h2 id="この-その-あの-どの" tabindex="-1">この／その／あの／どの <a class="header-anchor" href="#この-その-あの-どの" aria-label="Permalink to &quot;この／その／あの／どの&quot;">​</a></h2><p><strong>Rule:</strong> These are <strong>連体詞</strong> (words that modify a noun directly). They must be followed by a noun: この本 (“this book”), その本 (“that book near you / the book mentioned”), あの本 (“that book over there”), どの本 (“which book”). To refer to a thing without naming the noun, use これ／それ／あれ／どれ instead.</p><ul><li>この本は面白いです。 — This book is interesting.</li><li>これは面白いです。 — This is interesting.</li><li>どの本があなたのですか。 — Which book is yours?</li><li>どれがあなたのですか。 — Which one is yours?</li></ul><h2 id="n-を-n-をください" tabindex="-1">N を / N をください <a class="header-anchor" href="#n-を-n-をください" aria-label="Permalink to &quot;N を / N をください&quot;">​</a></h2><p><strong>Rule:</strong> The particle <strong>を</strong> follows a noun and marks the <strong>direct object</strong>. Japanese is an SOV language, so the verb usually comes at the end of the sentence; the object appears earlier and needs を to mark it.</p><p><strong>N をください:</strong> ください is the imperative of くださる (“to give”). <strong>N をください</strong> means “please give me …” and is common when shopping or ordering.</p><ul><li>水族館の入場券をください。 — Please give me an aquarium admission ticket.</li><li>チーズバーガーセットをください。 — Please give me a cheeseburger set.</li><li>ビールをください。 — Please give me a beer.</li></ul><p><strong>も:</strong> To say “also / too,” use <strong>も</strong>. も and を do not stack — も <strong>replaces</strong> を.</p><ul><li>それから、ホットコーヒーもください。 — And then, please give me a hot coffee too.</li></ul><h2 id="n-を-quantity-ください" tabindex="-1">N を (quantity) ください <a class="header-anchor" href="#n-を-quantity-ください" aria-label="Permalink to &quot;N を (quantity) ください&quot;">​</a></h2><p><strong>Rule:</strong> To say how many you want, put the <strong>quantifier</strong> (数量詞) before ください: <strong>N を [quantifier] ください</strong>. Quantifiers generally sit before the verb in Japanese.</p><ul><li>この水族館の入場券を3枚ください。 — Please give me three admission tickets for this aquarium. / はい、3000円です。 — Sure, that’ll be 3000 yen.</li><li>チーズバーガーセットを一つください。 — Please give me one cheeseburger set.</li><li>あのう、これを2本ください。 — Um, please give me two of these.</li><li>シャツを3枚ください。 — Please give me three shirts.</li></ul><p>Quantifiers also come before other verbs: 兄が2人います。 — I have two older brothers. / スマホが2台あります。 — There are two smartphones.</p><p>Counters used here: <strong>枚</strong> (flat objects), <strong>一つ</strong> (general), <strong>本</strong> (long/cylindrical), <strong>人</strong> (people), <strong>台</strong> (machines).</p><h2 id="n-をお願いします-n-でお願いします" tabindex="-1">N をお願いします / N でお願いします <a class="header-anchor" href="#n-をお願いします-n-でお願いします" aria-label="Permalink to &quot;N をお願いします / N でお願いします&quot;">​</a></h2><p><strong>Rule:</strong> <strong>お願いします</strong> is a polite request (“please”). It can replace <strong>ください</strong> in many ordering contexts.</p><ul><li>ホットコーヒーをお願いします。 — A hot coffee, please.</li><li>これを４つお願いします。 — Four of these, please.</li></ul><p><strong>N でお願いします:</strong> The particle <strong>で</strong> marks the <strong>means / method / chosen option</strong>. Use it when specifying size, payment, channel, and so on — especially when the item itself is already clear in context.</p><ul><li>Sサイズでお願いします。 — Small, please. (natural when the clerk already asked about size)</li><li>Sサイズのコーヒーをお願いします。 — A small coffee, please. (names the item)</li><li>アリペイでお願いします。 — Alipay, please. (at payment)</li><li>Eメールでお願いします。 — By email, please. (when asking how to contact)</li></ul><h2 id="n-でございます" tabindex="-1">N でございます <a class="header-anchor" href="#n-でございます" aria-label="Permalink to &quot;N でございます&quot;">​</a></h2><p><strong>Rule:</strong> <strong>でございます</strong> is a more polite / formal equivalent of <strong>です</strong> (丁寧語). It is common in service speech, speeches, and other formal settings. It is typically used for the speaker, the speaker’s in-group, or things belonging to them — not usually for the respected listener or the listener’s things.</p><ul><li>エレベーターはこちらでございます。 — The elevator is this way.</li><li>私が担当者でございます。 — I am the person in charge.</li><li>部長の田中でございます。 — This is Department Manager Tanaka. <em>(colleague introducing their own company’s manager to a client)</em></li></ul><p>Dialogue:</p><ul><li>A <em>(outsider)</em>: 田中部長は、今日、お休みですか。 — Is Manager Tanaka off today?</li><li>B <em>(colleague)</em>: はい、休みでございます。 — Yes, he is off today.</li></ul><h2 id="どうなさいますか-はどうですか" tabindex="-1">どうなさいますか / ～はどうですか <a class="header-anchor" href="#どうなさいますか-はどうですか" aria-label="Permalink to &quot;どうなさいますか / ～はどうですか&quot;">​</a></h2><p><strong>Rule:</strong> <strong>どう</strong> means “how / what (choice).” <strong>なさいます</strong> is the honorific form of <strong>する</strong>, so <strong>どうなさいますか</strong> is a very polite “What would you like?” / “How would you like it?” — common in service speech.</p><ul><li>A: ホットコーヒーのサイズはどうなさいますか。 — What size hot coffee would you like?</li><li>B: Lサイズでお願いします。 — Large, please.</li></ul><p><strong>～はどうですか:</strong> When <strong>どう</strong> is the predicate with <strong>ですか</strong>, <strong>～はどうですか</strong> asks for an opinion or how something is going.</p><ul><li>このコーヒーはどうですか。 — How is this coffee?</li><li>清華大学はどうですか。 — How is Tsinghua University?</li><li>最近はどうですか。 — How have you been lately?</li></ul><h2 id="adjective-predicates-polite-non-past" tabindex="-1">Adjective predicates (polite non-past) <a class="header-anchor" href="#adjective-predicates-polite-non-past" aria-label="Permalink to &quot;Adjective predicates (polite non-past)&quot;">​</a></h2><p><strong>Rule:</strong> Adjectival predicates describe a <strong>state</strong> or a <strong>constant property</strong>. Japanese adjectives fall into two types: <strong>Type I</strong> (い-adjectives, ending in <strong>い</strong>) and <strong>Type II</strong> (な-adjectives / adjectival verbs).</p><p><strong>Polite non-past (敬体):</strong></p><ol><li><strong>Affirmative:</strong> Type I → <strong>A₁ + です</strong>; Type II → <strong>A₂ + です</strong>.</li><li><strong>Negative:</strong> Type I → drop <strong>い</strong>, then <strong>く + ありません</strong>; Type II → <strong>A₂ + ではありません</strong> (spoken: <strong>じゃありません</strong>).</li></ol><table tabindex="0"><thead><tr><th>Category</th><th>Tense</th><th>Affirmative (polite)</th><th>Negative (polite)</th></tr></thead><tbody><tr><td>Type I (e.g. 高い)</td><td>Non-past</td><td>高いです</td><td>高くありません</td></tr><tr><td>Type II (e.g. 静か)</td><td>Non-past</td><td>静かです</td><td>静かではありません（じゃありません）</td></tr></tbody></table><p><strong>では</strong> can be replaced by <strong>じゃ</strong> in spoken Japanese.</p><ul><li>東京は寒いです。 — Tokyo is cold.</li><li>あの映画は面白くありません。 — That movie is not interesting.</li><li>先生は親切です。 — The teacher is kind.</li><li>日本語は簡単ではありません。 — Japanese is not easy.</li></ul><p><strong>いい:</strong> Conjugate from the older form <strong>よい</strong>. Negative of いいです → <strong>よくありません</strong>.</p><ul><li>成績はよくありません。 — The grades are not good.</li></ul><h2 id="n1-は-n2-が-〜" tabindex="-1">N₁ は N₂ が 〜 <a class="header-anchor" href="#n1-は-n2-が-〜" aria-label="Permalink to &quot;N₁ は N₂ が 〜&quot;">​</a></h2><p><strong>Rule:</strong> <strong>は</strong> marks the <strong>topic</strong> (what the sentence is about); <strong>が</strong> marks the <strong>subject</strong> of the predicate that follows. In <strong>A は B が X です</strong>, A is usually a person or a whole thing, B is a part or aspect of A, and <strong>B が X です</strong> describes a property of A. This “topic + part/aspect” pattern is common in Japanese and often differs from how Chinese or English packages the same idea.</p><ul><li>象は鼻が長いです。 — Elephants have long trunks. / An elephant’s trunk is long.</li><li>富士山は形がいいです。 — Mt. Fuji has a nice shape.</li><li>今日は天気がいいです。 — The weather is good today.</li><li>彼女は性格が明るいです。 — She has a cheerful personality.</li></ul><h2 id="あまり-そんなに-adjective-negative" tabindex="-1">あまり / そんなに + adjective (negative) <a class="header-anchor" href="#あまり-そんなに-adjective-negative" aria-label="Permalink to &quot;あまり / そんなに + adjective (negative)&quot;">​</a></h2><p><strong>Rule:</strong> The degree adverbs <strong>あまり</strong> and <strong>そんなに</strong> with a <strong>negative</strong> adjective mean “not very …” / “not that …”. Use them with the polite negative forms of Type I and Type II adjectives (e.g. 寒くありません, 難しくありません).</p><ul><li>A: 東京は寒いですか。 — Is Tokyo cold?</li><li>B: いいえ、あまり寒くありません。 — No, it’s not very cold.</li><li>日本語はそんなに難しくありません。 — Japanese is not that difficult.</li><li>このパソコンはそんなに遅くありません。 — This computer is not that slow.</li></ul><h2 id="〜から-reason" tabindex="-1">〜から（reason） <a class="header-anchor" href="#〜から-reason" aria-label="Permalink to &quot;〜から（reason）&quot;">​</a></h2><p><strong>Rule:</strong> <strong>から</strong> at the end of a clause or sentence marks a <strong>reason / cause</strong> (“because …”). It can stand alone as an answer or follow a statement that gives the conclusion first.</p><ul><li>（中村さんは）とても真面目ですから。 — Because (Nakamura-san) is very serious / diligent.</li><li>アイスクリームがいいです。暑いですから。 — Ice cream would be good. Because it’s hot.</li><li>A: 寒いですね。 — It’s cold, isn’t it?</li><li>B: そうですね。今日は雪ですから。 — Yes. Because it’s snowing today.</li></ul><h2 id="n-はどうですか-asking-about-nature-opinion" tabindex="-1">N はどうですか（asking about nature / opinion） <a class="header-anchor" href="#n-はどうですか-asking-about-nature-opinion" aria-label="Permalink to &quot;N はどうですか（asking about nature / opinion）&quot;">​</a></h2><p><strong>Rule:</strong> <strong>どう</strong> means “how / what is it like.” <strong>N はどうですか</strong> asks about the <strong>nature</strong> of something or the listener’s <strong>opinion</strong> of it. Answer with an adjectival predicate (or a short evaluative phrase).</p><ul><li>A: 日本の留学生生活はどうですか。 — How is life as an international student in Japan?</li><li>B: 順調ですよ。 — It’s going well.</li><li>A: 日本語はどうですか。 — How is Japanese?</li><li>B: 難しいです。 — It’s difficult.</li><li>A: この映画はどうですか。 — How is this movie?</li><li>B: とても面白いです。 — It’s very interesting.</li></ul><h2 id="〜よ-assertion-emphasis" tabindex="-1">〜よ（assertion / emphasis） <a class="header-anchor" href="#〜よ-assertion-emphasis" aria-label="Permalink to &quot;〜よ（assertion / emphasis）&quot;">​</a></h2><p><strong>Rule:</strong> Sentence-final <strong>よ</strong> marks the speaker’s <strong>assertion</strong>, strong claim, or emphatic tone — often new information or a firm reminder for the listener.</p><ul><li>中村さんのおかげですよ。 — It’s thanks to Nakamura-san.</li><li>山羊座の人はみんな真面目ですよ。 — Capricorns are all serious / diligent.</li><li>日本語はそんなに難しくありませんよ。 — Japanese isn’t that difficult.</li></ul><h2 id="〜ね-soft-exclamation" tabindex="-1">〜ね（soft exclamation） <a class="header-anchor" href="#〜ね-soft-exclamation" aria-label="Permalink to &quot;〜ね（soft exclamation）&quot;">​</a></h2><p><strong>Rule:</strong> Sentence-final <strong>ね</strong> can mark a <strong>light exclamation / shared impression</strong>. Read it with a <strong>falling</strong> tone (↘). For a softer stretch, lengthen it to <strong>ねえ</strong>.</p><ul><li>由加ちゃんはすごいですね。↘ — Yuka-chan is really amazing.</li><li>この洋服、かわいいですね。↘ — These clothes are cute.</li><li>由加ちゃんのこのスマホケース、かわいいですね。↘ — Yuka-chan, this phone case of yours is cute.</li></ul>',95)])])}const u=e(s,[["render",r]]);export{c as __pageData,u as default};
